// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Arrange: set owner to this contract to call onlyOwner functions
        vm.prank(address(this));

        // Act: call AdjustBetAmounts with the fuzzed amount
        c.AdjustBetAmounts(amount);

        // Assert: the public getter should return the amount we passed in
        assertTrue(c.currentBetLimit() == amount);
    }
}

